"""Author and apply the 28 optional climate reviews; retain original exam scope."""
from pathlib import Path
from urllib.parse import quote
import json,re

root=Path(__file__).resolve().parents[1]
url='https://github.com/0183ty2512/lao-san-yang/blob/main/'+quote('50日任务/复核依据/气候拓展复核.md')
data={}
def add(ids,note,answer,key):
    for q in ids.split():
        data[q]={'status':'内容复核（2026-11-03；原卷标略，拓展选读）','note':note+' 原卷标略，仍作选读。'+f'[补充依据]({url}#{key})','answer':answer}

feedback='温度上升使饱和水汽压增大；在大尺度相对湿度变化较小的条件下，水汽增多、红外吸收增强，构成正反馈。冰雪减少、反照率降低也是正反馈；升温增强向外长波发射的普朗克响应是负反馈。云的局地效应随云高、云量、云相态变化；IPCC AR6 对全球净云反馈的评估为正（高信度），不能把“各类云效应不同”写成全球净符号完全未知。'
climate='气候变化是气候均值、变率等统计属性的持续变化，通常跨越数十年或更长时间，不能由一次冷暖天气判定。自然外强迫、人为强迫及内部变率均可影响气候；反馈是对初始变化的响应，不能混作独立外强迫。'
add('2021-一-6 2018-一-3','核对统计定义、强迫和反馈的区别；更正“空气容纳水汽”表述并补充全球净云反馈的评估。',climate+'\n\n'+feedback,'c01')
add('2015-二-1','按对初始温度扰动的增强或削弱判断正负反馈；区分局地云辐射效应与全球净云反馈。',feedback,'c01')
add('2021-二-5','辐射冷却与冷平流机制正确；补充植物表面温度可低于气象站气温，有无白霜不能单独判断冻害。','霜冻是植物组织遭低温冻结损伤的过程。晴空弱风夜间地表净长波损失可使植物表面和近地层强烈冷却，形成辐射霜冻；冷气团入侵产生平流霜冻，二者也可共同作用。低洼地冷空气积聚会加重风险。\n\n植物表面温度可能低于标准高度的气温，因此站点气温略高于零度也不能排除局地冻害；是否出现可见白霜还取决于湿度。临界损伤温度随物种、生育期和持续时间而变，不能统一等同于零摄氏度。','c02')
flux=r'显热和潜热的整体交换公式可写为 $H=\rho_a c_p C_H U_r(T_s-T_a)$、$LE=\rho_a L_v C_E U_r(q_s-q_a)$，向上为正。$U_r$ 是近海面空气相对海流的速度大小；$q_s$ 取海表温度下的饱和比湿（精细计算考虑盐度），交换系数随稳定度等条件变化。量纲均为单位面积功率。'
add('2021-三-2','核对显热和潜热通量符号与量纲；明确相对风速、交换系数和能量传递不等于全部转化为机械功。','海气交换包括短长波辐射、显热、潜热和风应力做功。海洋蒸发时失去潜热，水汽在大气中凝结时释放潜热；吸收的热量并非全部变成环流动能。\n\n'+flux+'\n\n风应力向海洋传递动量和机械能，驱动海流与混合；海温、海冰和海流变化又影响大气温湿差及交换，构成双向耦合。','c03')
model='气候模式是气候系统或其部分的数学表示，包含从简化能量收支模式到复杂耦合模式的层次。以耦合大气—海洋模式为例，数值求解动力、热力和辐射方程，表示陆面与海冰过程，并参数化未解析过程；不是所有气候模式都必须显式耦合全部圈层。\n\n给定外强迫、初始条件和边界条件后作长期积分或集合，研究统计气候及响应。未来投影依赖排放情景、模式结构及内部变率；它不能准确指定几十年后某一天的天气。'
add('2020-一-4 2016-一-4 2015-一-8','核对数值模拟和气候投影的含义；将全耦合描述限定为复杂模式示例，避免排除简化气候模式。',model,'c04')
human='人类活动主要通过三条途径影响气候：燃烧化石燃料、土地利用等增加温室气体，改变长波收支；气溶胶散射或吸收辐射并改变云过程，净效应取决于类型与分布；土地利用改变反照率、蒸散、粗糙度和碳收支，影响地表能量分配。\n\n城市储热、蒸散减少、人为热排放和通风变化可形成局地热岛，但热岛不能单独解释全球海陆增暖。太阳、火山和内部变率可作为归因比较项，不应占据“人类影响方式”答案的主线。'
add('2020-三-3 2017-二-5 2014-二-3','按题目重写人为影响的三条主线，减少泛列自然驱动的重复内容；区分局地热岛与全球归因。',human,'c05')
add('2019-二-4','核对 Bjerknes 正反馈和海洋调整的终止机制；ENSO 非严格周期，暖事件消退不必立即转为拉尼娜。','厄尔尼诺是 ENSO 的暖位相：赤道中东太平洋海温持续偏暖，并与大气环流异常耦合。典型发展反馈是信风减弱、温跃层倾斜减小及东部冷水补给减弱，使海温升高；对流东移又削弱东西压差和信风，放大初始异常。\n\n赤道波传播、海洋热含量充放电及季节演变使系统重新调整，限制暖事件并可促成转相。各事件的起因、空间型和持续时间不同，不能把整个过程写成严格固定周期或必然紧接冷事件。','c06')
ocean='海洋大热容量使其能够吸收、储存并缓慢释放热量，影响气候变化的幅度和滞后；海流经向输热，重新分配低纬能量。海温和海冰改变海气显潜热、辐射及反照率，海气耦合可产生 ENSO 等内部变率。\n\n海洋还吸收和储存一部分人为排放的二氧化碳，通过溶解、环流和生物过程影响大气碳收支。海洋吸碳能力并非固定不变。\n\n大尺度翻转与温盐密度差、风和混合共同相关；“全球传送带”是示意图，不能理解成仅由密度差驱动的一条闭合水流。海气影响双向发生，不是海洋单向加热大气。'
add('2019-三-2 2017-二-4 2015-三-1 2013-四-1','核对储热、输热和双向耦合，补充海洋碳汇；去除与本题无关的逐项通量公式重复。',ocean,'c07')
add('2018-二-2','核对纬向积分收支，补充有时段和纬度限定的南北半球对比，避免只写“有差异”而未回答差异。',r'两半球在气候平均下均需向极输送能量，大气与海洋的分担受海陆分布、海洋通道和环流影响。以 Trenberth 与 Caron（2001）针对 1985 年 2 月至 1989 年 4 月的估计为例，在南北纬各约 $35^\circ$ 的总输送峰值附近，大气约占北半球的 78%、南半球的 92%；该例中北半球海洋分担相对较大。这是指定资料与纬度的估计，不能推广为所有纬度和时期的固定比例。'+'\n\n'+r'定义 $F(\varphi)$ 向北为正，$R_{\mathrm{TOA}}$ 为向下净辐射，则长期平均且储热可忽略时 $\frac{dF}{d\varphi}=2\pi a^2\cos\varphi\,R_{\mathrm{TOA}}(\varphi)$。非稳态需将右侧净辐射减去柱总能量储存率。南半球向极输送对应负的 $F$，比较强度应比较绝对值。','c08')
land='陆面通过反照率改变吸收短波，通过土壤水分和植被蒸散改变潜热，通过粗糙度改变湍流交换；土壤热容量和导热率影响储热与日变化，积雪兼有增反照率和隔热作用。植被还参与碳循环。\n\n在可用能量等条件相近时，干土蒸发受限通常使显热比例增加，有利近地层增暖；实际温度还受云、平流和边界层混合影响。造林同时改变反照率、蒸散和碳收支，净温度效应依地区、季节与时间尺度而定。'
add('2018-二-3 2016-三-1','按辐射、显潜热、储热和动量交换核对陆面过程；补充土壤和积雪条件，避免将干土或植被效应绝对化。',land,'c09')
add('2017-一-6','区分统计分布尾部的少见事件与持续气候状态转变；定义须说明地区、基准期和持续时间。','极端天气事件是在特定地点和季节中少见的事件；持续一段时间并形成异常季节平均或累计量时，可讨论极端气候事件。识别阈值可用给定基准期的分位数等统计量，须注明地区、季节、变量和持续时间。\n\n一次极端事件不等于气候发生突变；事件是否受气候变化影响需要另作归因分析。','c10')
add('2016-一-5','核对相对时间尺度与持续性；非线性阈值是可能机制，不把一次极端天气当气候突变。','气候突变指相对该系统以往典型变化速率显著更快、并持续的气候状态变化。非线性反馈或越过阈值可触发突变，但“突变”的判定还需时间尺度、空间范围及持续性证据。短暂寒潮或单日极端高温不自动构成气候突变。','c10')
add('2015-一-2','核对气候系统五个主要组成及能量、水和碳的交换；删去与名词解释重复的长篇驱动罗列。','气候系统由大气圈、水圈、冰冻圈、岩石圈/陆地表面和生物圈及其相互作用构成。它们通过辐射、热量、动量、水和碳等交换耦合；系统受外强迫影响，也具有内部变率。气候是天气的长期统计特征，不能把气候系统仅等同于大气。','c04')
add('2014-一-4','核对遥相关的空间联系及动力解释；相关不自动建立单向因果。','遥相关是相距遥远地区的环流或气候异常之间的统计联系。热带加热异常可激发行星波列影响中高纬，也可能有共同强迫驱动多个地区。解释时应结合波传播、环流结构和共同驱动因素；仅有相关系数不能认定某一区域单向导致另一区域变化。','c06')
add('2014-二-1','核对仪器记录与多类代用资料；补充定年、校准、时空代表性及不确定度。','仪器期可使用经质量控制的地面、海洋和卫星记录；更早期通过树轮、冰芯、珊瑚、洞穴及湖海沉积、历史文献等代用资料重建。\n\n各指标响应的气候变量、季节和地区不同，需建立年代及指标—气候关系，检验稳定性并估计不确定度。某地树轮宽度或同位素比值不能直接等同于全球平均温度，应进行多源对比和空间重建。','c11')
add('2014-四-2','核对辐射背景、地表收支和城市机制；区分地表皮肤温度与标准高度近地气温。','地表气温受纬度和季节控制的太阳辐射、海拔、海陆位置、洋流、云、平流及垂直混合影响。反照率、土壤湿度、植被与粗糙度通过地表净辐射、显热、潜热和储热进一步调节近地气温。\n\n城市建筑储热、蒸散减少、人为热和街谷通风变化可造成热岛，晴静夜间常较明显；实际强度依天气与城市形态变化。地表辐射皮肤温度不等于标准观测高度的空气温度。','c09')
add('2012-二-3','逐项核对吸收发射、传输方程符号和积分解；明确局地热力平衡、无散射及光学厚度方向。',r'水汽、二氧化碳、甲烷、氧化亚氮、臭氧及部分含卤气体在红外谱带吸收并发射辐射。地气能量仍须向太空散失，温室效应不是把能量永久锁住，也不等于臭氧空洞。'+'\n\n'+r'在无散射、局地热力平衡下，沿传播路径有 $\frac{dI_\nu}{ds}=-k_\nu\rho I_\nu+k_\nu\rho B_\nu(T)$。令光学厚度从入射端向前增长，则 $I_\nu(\tau)=I_\nu(0)e^{-\tau}+\int_0^\tau B_\nu[T(t)]e^{-(\tau-t)}dt$；两项分别表示边界辐射衰减与沿途各层发射的贡献。'+'\n\n'+'温室气体增加在原温度场下改变向外净长波与有效辐射高度，造成能量失衡，系统随后调整。长寿命二氧化碳的外加变化可作为强迫，水汽变化通常是反馈；不能只写吸收而忽略大气自身发射。','c12')
add('2012-四-2','核对地形动力与热力作用及实例；恢复精简时缺失的热力主线，不增加原题没有的“四种以上”要求。','动力作用：高大地形可迫使气流绕行或爬升，改变急流、定常波和下游槽脊；迎风抬升易凝结降水，背风下沉可形成雨影，但需水汽、风向与层结配合。\n\n热力作用：高原地表的感热、潜热及辐射收支具有季节变化，能影响热源配置、季风和大尺度环流。青藏高原可用作机械阻挡及季节热力作用的综合实例；不能把“高处更接近太阳”作为加热机制。\n\n山脉还改变雨带位置、积雪与植被分布，产生陆面反馈。应区分一次地形雨的天气过程与多年平均的迎背风降水差异。','c09')
add('2011-四-1','区分候选物理机制和观测归因；补充权威评估，不把自然与人为贡献并列成同等解释。',climate+'\n\n'+'近百年变化可讨论温室气体、气溶胶、土地利用、太阳与火山强迫及内部变率，但列出这些机制并不能确定各自贡献。IPCC AR6 第三章综合观测与归因证据确认人类影响造成现代增暖，只有包含人为影响的模拟才能重现观测到的长期全球增暖；具体时段的分量需使用对应归因结果。\n\n'+feedback,'c05')

assert len(data)==28
(root/'scripts/review_optional.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
count={q:0 for q in data}
canonical={}
for p in sorted((root/'每日内容').glob('D*.md')):
    text=p.read_text(encoding='utf-8')
    for q in data:
        m=re.search(r'^### '+re.escape(q)+r' ·[^\n]*\n([\s\S]*?)(?=^#{1,3} |\Z)',text,re.M)
        if m and q not in canonical:
            body=m[1]
            links=re.search(r'^\[解析来源[^\n]+',body,re.M)
            if links:
                cleaned=re.sub(r'^\*\*本次复核提示（[^\n]*\n','',body,flags=re.M).lstrip()
                canonical[q]=(cleaned.split('\n\n')[0],links[0])
assert len(canonical)==len(data)
for p in (root/'每日内容').glob('D*.md'):
    text=p.read_text(encoding='utf-8')
    for q,e in data.items():
        pattern=r'^(### '+re.escape(q)+r' ·[^\n]*)\n([\s\S]*?)(?=^#{1,3} |\Z)'
        def update(m):
            count[q]+=1
            first,links=canonical[q]
            return m[1]+'\n\n**本次复核提示（2026-11-03）：** '+e['note']+'\n\n'+first+'\n\n'+links+'\n\n**拓展选读解析：**\n\n'+e['answer']+'\n\n'
        text=re.sub(pattern,update,text,flags=re.M)
    p.write_text(text,encoding='utf-8')
assert all(count.values()),count
print('Optional questions',len(data),'occurrences',sum(count.values()))
